import pyomo.environ as pyo

DATA = {
    "foods": ["brownie", "icecream", "cola", "cheesecake"],
    "nutrients": ["calories", "chocolate", "sugar", "fat"],
    "cost": {
        "brownie": 50,
        "icecream": 20,
        "cola": 30,
        "cheesecake": 80,
    },
    "content": {
        # nutrient: {food: amount per unit}
        "calories": {"brownie": 400, "icecream": 200, "cola": 150, "cheesecake": 500},
        "chocolate": {"brownie": 3, "icecream": 2, "cola": 0, "cheesecake": 0},
        "sugar": {"brownie": 2, "icecream": 2, "cola": 4, "cheesecake": 4},
        "fat": {"brownie": 2, "icecream": 4, "cola": 1, "cheesecake": 5},
    },
    "requirement": {
        "calories": 500,
        "chocolate": 6,
        "sugar": 10,
        "fat": 8,
    },
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.FOODS = pyo.Set(initialize=d["foods"])
    model.NUTRIENTS = pyo.Set(initialize=d["nutrients"])

    # Variables: units of each food eaten per day
    model.x = pyo.Var(model.FOODS, within=pyo.NonNegativeReals, bounds=(0, None))

    # Objective: minimise total daily cost
    def obj_rule(m):
        return sum(d["cost"][i] * m.x[i] for i in m.FOODS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Constraints: each nutrient intake must meet its requirement
    def nutrient_rule(m, n):
        return sum(d["content"][n][i] * m.x[i] for i in m.FOODS) >= d["requirement"][n]

    model.nutrient_req = pyo.Constraint(model.NUTRIENTS, rule=nutrient_rule)

    return model

import pyomo.environ as pyo

DATA = {
    "foods": ["brownies", "chocolate_ice_cream", "cola", "pineapple_cheesecake"],
    "nutrients": ["calories", "chocolate", "sugar", "fat"],
    # cost in cents per unit of each food
    "cost": {
        "brownies": 50,
        "chocolate_ice_cream": 20,
        "cola": 30,
        "pineapple_cheesecake": 80,
    },
    # nutrient content per unit of each food
    "content": {
        "calories": {
            "brownies": 400,
            "chocolate_ice_cream": 200,
            "cola": 150,
            "pineapple_cheesecake": 500,
        },
        "chocolate": {
            "brownies": 3,
            "chocolate_ice_cream": 2,
            "cola": 0,
            "pineapple_cheesecake": 0,
        },
        "sugar": {
            "brownies": 2,
            "chocolate_ice_cream": 2,
            "cola": 4,
            "pineapple_cheesecake": 4,
        },
        "fat": {
            "brownies": 2,
            "chocolate_ice_cream": 4,
            "cola": 1,
            "pineapple_cheesecake": 5,
        },
    },
    # minimum daily requirement for each nutrient
    "requirement": {
        "calories": 500,
        "chocolate": 6,
        "sugar": 10,
        "fat": 8,
    },
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.FOODS = pyo.Set(initialize=d["foods"])
    model.NUTRIENTS = pyo.Set(initialize=d["nutrients"])

    # Decision: units of each food consumed per day
    model.x = pyo.Var(model.FOODS, within=pyo.NonNegativeReals)

    # Objective: minimize total daily cost (cents)
    def obj_rule(m):
        return sum(d["cost"][f] * m.x[f] for f in m.FOODS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # One constraint per nutrient: total intake must meet the minimum requirement
    def nutrient_rule(m, n):
        return sum(d["content"][n][f] * m.x[f] for f in m.FOODS) >= d["requirement"][n]

    model.nutrient_requirement = pyo.Constraint(model.NUTRIENTS, rule=nutrient_rule)

    return model
